use soroban_sdk::{contractimpl, Address, Env};

use crate::errors::ContractError;
use crate::{admin, events, storage};
// Items generated by the #[contract] macro; needed so `impl SkillSyncEscrow` can live in this file
use crate::{SkillSyncEscrow, SkillSyncEscrowArgs, SkillSyncEscrowClient};

/// Platform fee ceiling: 1000 bps = 10%.
// Hard cap enforced on-chain, so even a compromised admin can't set a punitive fee
pub const MAX_PLATFORM_FEE_BPS: u32 = 1000;

// Admin-configurable settings: platform fee, treasury address and dispute window.
// Each setter follows the same pattern: check admin -> require their signature ->
// validate the input -> store the new value -> emit an event with the old and new values.
#[contractimpl]
impl SkillSyncEscrow {
    /// Sets the platform fee in basis points (0-1000). Admin only.
    pub fn set_platform_fee(env: Env, new_fee_bps: u32) -> Result<(), ContractError> {
        // Fails with NotInitialized if no admin has been stored yet
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        if new_fee_bps > MAX_PLATFORM_FEE_BPS {
            return Err(ContractError::FeeTooHigh);
        }
        // Read the previous value so the event can report the change
        let old = storage::get_platform_fee(&env);
        storage::set_platform_fee(&env, new_fee_bps);
        // The event names the signing admin as well as both fee values
        events::emit_platform_fee_updated(&env, old, new_fee_bps, &admin);
        Ok(())
    }

    /// Current platform fee in basis points.
    // Public read-only getter, no auth needed
    pub fn get_platform_fee(env: Env) -> u32 {
        storage::get_platform_fee(&env)
    }

    /// Changes the wallet that receives platform fees. Admin only.
    pub fn set_treasury(env: Env, new_treasury: Address) -> Result<(), ContractError> {
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        // Also doubles as an initialization check: errors if no treasury was ever set
        let old = admin::require_treasury(&env)?;
        storage::set_treasury(&env, &new_treasury);
        // The event records the signing admin as well as both wallets
        events::emit_treasury_updated(&env, &old, &new_treasury, &admin);
        Ok(())
    }

    /// The wallet that receives platform fees.
    pub fn get_treasury(env: Env) -> Result<Address, ContractError> {
        admin::require_treasury(&env)
    }

    /// Sets how many ledgers a buyer has to react after a session is marked
    /// complete. Admin only; must be at least one ledger.
    pub fn set_dispute_window(env: Env, window_ledgers: u32) -> Result<(), ContractError> {
        let admin = admin::require_admin(&env)?;
        admin.require_auth();
        // A zero window would make auto_refund available immediately after completion
        if window_ledgers == 0 {
            return Err(ContractError::InvalidWindow);
        }
        let old = storage::get_dispute_window(&env);
        storage::set_dispute_window(&env, window_ledgers);
        events::emit_dispute_window_updated(&env, old, window_ledgers);
        Ok(())
    }

    /// The dispute window in ledgers (default 1000).
    pub fn get_dispute_window(env: Env) -> u32 {
        storage::get_dispute_window(&env)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_utils::setup;
    use soroban_sdk::testutils::{Address as _, Events};
    use soroban_sdk::{IntoVal, Symbol};

    // A freshly initialized contract charges no fee until the admin sets one
    #[test]
    fn platform_fee_defaults_to_zero_and_can_be_updated() {
        let f = setup();
        assert_eq!(f.client.get_platform_fee(), 0);
        f.client.set_platform_fee(&250);
        assert_eq!(f.client.get_platform_fee(), 250);
    }

    // The PlatformFeeUpdated event reports both fee values and the admin who signed
    #[test]
    fn set_platform_fee_emits_both_values_and_the_admin() {
        let f = setup();
        f.client.set_platform_fee(&250);
        f.client.set_platform_fee(&100);

        let (_, topics, data) = f.env.events().all().last().unwrap();
        assert_eq!(
            topics,
            (Symbol::new(&f.env, "PlatformFeeUpdated"),).into_val(&f.env)
        );
        // (old_fee_bps, new_fee_bps, updated_by)
        let data: (u32, u32, Address) = data.into_val(&f.env);
        assert_eq!(data, (250, 100, f.admin.clone()));
    }

    // Boundary test: exactly 1000 bps is allowed, 1001 is rejected and the old value is kept
    #[test]
    fn platform_fee_is_capped_at_ten_percent() {
        let f = setup();
        f.client.set_platform_fee(&1000);
        assert_eq!(
            f.client.try_set_platform_fee(&1001),
            Err(Ok(ContractError::FeeTooHigh))
        );
        assert_eq!(f.client.get_platform_fee(), 1000);
    }

    // With all mocked auths cleared, no admin signature is present, so every setter must fail
    #[test]
    fn config_changes_are_admin_only() {
        let f = setup();
        f.env.mock_auths(&[]);
        assert!(f.client.try_set_platform_fee(&100).is_err());
        assert!(f.client.try_set_treasury(&Address::generate(&f.env)).is_err());
        assert!(f.client.try_set_dispute_window(&500).is_err());
    }

    // The treasury comes from initialization and can later be swapped for a new address
    #[test]
    fn treasury_is_set_at_initialize_and_can_change() {
        let f = setup();
        assert_eq!(f.client.get_treasury(), f.treasury);
        let next = Address::generate(&f.env);
        f.client.set_treasury(&next);
        assert_eq!(f.client.get_treasury(), next);
    }

    // The TreasuryUpdated event names both wallets and the admin who signed the change
    #[test]
    fn set_treasury_emits_both_wallets_and_the_admin() {
        let f = setup();
        let old = f.treasury.clone();
        let next = Address::generate(&f.env);
        f.client.set_treasury(&next);

        let (_, topics, data) = f.env.events().all().last().unwrap();
        assert_eq!(
            topics,
            (Symbol::new(&f.env, "TreasuryUpdated"),).into_val(&f.env)
        );
        let data: (Address, Address, Address) = data.into_val(&f.env);
        assert_eq!(data, (old, next, f.admin.clone()));
    }

    // Default is 1000 ledgers (about 83 minutes); the admin can change it
    #[test]
    fn dispute_window_defaults_to_1000_ledgers() {
        let f = setup();
        assert_eq!(f.client.get_dispute_window(), 1000);
        f.client.set_dispute_window(&2000);
        assert_eq!(f.client.get_dispute_window(), 2000);
    }

    // Zero is rejected (see the comment in set_dispute_window)
    #[test]
    fn dispute_window_must_be_positive() {
        let f = setup();
        assert_eq!(f.client.try_set_dispute_window(&0), Err(Ok(ContractError::InvalidWindow)));
    }

    // Uses a bare, never-initialized contract: admin-gated calls and the treasury getter
    // must report NotInitialized rather than panic
    #[test]
    fn setters_fail_before_initialize() {
        let env = Env::default();
        env.mock_all_auths();
        let id = env.register(SkillSyncEscrow, ());
        let client = SkillSyncEscrowClient::new(&env, &id);
        assert_eq!(client.try_set_platform_fee(&10), Err(Ok(ContractError::NotInitialized)));
        assert_eq!(client.try_get_treasury(), Err(Ok(ContractError::NotInitialized)));
    }
}